import * as THREE from "three";

export const NAMETAG_PX_Y = 36;
export const NAMETAG_HAT_EXTRA_Y = 3;
export const NAMETAG_CAP_PX = 2.4;
export const NAMETAG_LAYER = 1;
export const DEFAULT_NAMETAG_FONT = '"MinecraftTen", "Minecraft", sans-serif';

export interface NametagOptions {
  text: string;
  iconUrl?: string | null;
  iconPlus?: boolean;
  font?: string;
}

export interface NametagHandle {
  mesh: THREE.Mesh;
  ready: Promise<void>;
  dispose(): void;
}

function loadIcon(url: string): Promise<HTMLImageElement | null> {
  return new Promise((resolve) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => resolve(img);
    img.onerror = () => resolve(null);
    img.src = url;
  });
}

export function createNametag(tag: NametagOptions): NametagHandle {
  const SS = 4;
  const fontPx = 48;
  const padX = 18;
  const padY = 16;
  const iconGap = 12;
  const font = tag.font ?? DEFAULT_NAMETAG_FONT;
  const fontSpec = `${fontPx}px ${font}`;
  const text = tag.text;
  const iconPlus = tag.iconPlus ?? false;

  const canvas = document.createElement("canvas");
  const material = new THREE.MeshBasicMaterial({
    transparent: true,
    side: THREE.DoubleSide,
    toneMapped: false,
    depthWrite: false,
  });
  material.depthTest = false;

  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), material);
  mesh.rotation.y = Math.PI;
  mesh.layers.set(NAMETAG_LAYER);

  let iconImg: HTMLImageElement | null = null;

  const paint = () => {
    let ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.font = fontSpec;
    const m = ctx.measureText(text);
    const ascent = m.actualBoundingBoxAscent || fontPx * 0.72;
    const textW = Math.ceil(m.width);
    const iconSize = iconImg ? Math.round(ascent * 1.3) : 0;
    const iconBlock = iconImg ? iconSize + iconGap : 0;
    const contentH = Math.ceil(ascent);
    const w = iconBlock + textW + padX * 2;
    const h = contentH + padY * 2;
    canvas.width = w * SS;
    canvas.height = h * SS;
    ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.scale(SS, SS);
    ctx.font = fontSpec;
    ctx.textBaseline = "alphabetic";
    ctx.fillStyle = "rgba(0,0,0,0.3)";
    ctx.fillRect(0, 0, w, h);

    if (iconImg) {
      const frame = Math.min(iconImg.naturalWidth, iconImg.naturalHeight);
      const frameY = iconPlus && iconImg.naturalHeight >= frame * 2 ? frame : 0;
      ctx.imageSmoothingEnabled = false;
      ctx.drawImage(
        iconImg,
        0,
        frameY,
        frame,
        frame,
        padX,
        (h - iconSize) / 2,
        iconSize,
        iconSize
      );
    }

    ctx.fillStyle = "#ffffff";
    ctx.textAlign = "left";
    ctx.fillText(text, padX + iconBlock, padY + ascent + (contentH - ascent) / 2);

    material.map?.dispose();
    const tex = new THREE.CanvasTexture(canvas);
    tex.magFilter = THREE.NearestFilter;
    tex.minFilter = THREE.NearestFilter;
    tex.colorSpace = THREE.SRGBColorSpace;
    material.map = tex;
    material.needsUpdate = true;
    const unit = NAMETAG_CAP_PX / ascent;
    mesh.scale.set(w * unit, h * unit, 1);
  };

  paint();

  const font$ = document.fonts
    ? document.fonts.load(fontSpec, text).then(paint, () => {})
    : Promise.resolve();
  const icon$ = tag.iconUrl
    ? loadIcon(tag.iconUrl).then((img) => {
        iconImg = img;
        paint();
      })
    : Promise.resolve();

  const ready = Promise.all([font$, icon$]).then(() => {});

  return {
    mesh,
    ready,
    dispose() {
      material.map?.dispose();
      material.dispose();
      mesh.geometry.dispose();
    },
  };
}
